### Python

```python
import sys
import bisect

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    T = int(data[0])
    idx = 1
    out = []
    for _ in range(T):
        n = int(data[idx]); idx += 1
        arr = list(map(int, data[idx:idx+n])); idx += n

        tail = []
        for x in arr:
            pos = bisect.bisect_right(tail, x)   # 非递降序列，找第一个大于x的位置
            if pos == len(tail):
                tail.append(x)
            else:
                tail[pos] = x

        L = len(tail)
        ans = (n - L + 1) // 2
        out.append(str(ans))

    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    solve()
