### Java

```java
import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int T = sc.nextInt();
        StringBuilder sb = new StringBuilder();

        while (T-- > 0) {
            int n = sc.nextInt();
            int[] arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = sc.nextInt();
            }

            // tail 用于维护最长非递降子序列的末尾元素
            ArrayList<Integer> tail = new ArrayList<>();
            for (int x : arr) {
                // 在非递降序列中找第一个大于x的位置（对应bisect_right）
                int pos = binarySearchRight(tail, x);
                if (pos == tail.size()) {
                    tail.add(x);
                } else {
                    tail.set(pos, x);
                }
            }

            int L = tail.size();
            int ans = (n - L + 1) / 2;
            sb.append(ans).append("\n");
        }
        System.out.print(sb);
    }

    // 返回 tail 中第一个大于 x 的下标，若不存在则返回 tail.size()
    private static int binarySearchRight(ArrayList<Integer> tail, int x) {
        int left = 0, right = tail.size();
        while (left < right) {
            int mid = left + (right - left) / 2;
            if (tail.get(mid) <= x) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }
        return left;
    }
}
